// Proposal 02: fixed take rows and a separate notes area; previous layout stays comparable.
const controlReviewItems=[['rows','Take-regels blijven even groot'],['notes','Eén vaste plek voor notes'],['timeline','Sessieplan blijft een tijdlijn'],['details','Minder tekst en timers in beeld']];
let controlReviewChoices={};try{controlReviewChoices=JSON.parse(localStorage.getItem('mandocues-controls-review')||'{}');}catch{}
function controlReview(){return `<details class="control-review"><summary>Wat is veranderd? · beoordeel per aanpassing</summary><p>Vergeleken met de vorige versie van dit prototype. Je beoordeling verandert de demo niet.</p>${controlReviewItems.map(([id,label])=>`<div><span>${label}</span><div role="group" aria-label="Beoordeling: ${label}">${['Goed','Liever terug','Twijfel'].map(value=>`<button data-control-review="${id}" data-review-value="${value}" aria-pressed="${controlReviewChoices[id]===value}">${value}</button>`).join('')}</div></div>`).join('')}<button data-action="download-control-review">Bewaar beoordeling ↓</button></details>`;}
function controlVersionButtons(s){return `<div class="control-version"><div role="group" aria-label="Compare layouts"><button data-control-version="new" aria-pressed="${!s.controlsPrevious}">New layout</button><button data-control-version="previous" aria-pressed="${!!s.controlsPrevious}">Previous layout</button></div><button data-action="fullscreen-prototype">⛶ Full screen</button></div>`;}
function cueTimeline(s){
 const minutes=cues.map((_,j)=>cuePlannedMinutes(j)),total=minutes.reduce((a,b)=>a+b,0);
 return `<section class="cue-timeline source-cue-plan" aria-label="Session plan timeline"><header><b>Session plan</b><small>10:00 — ${planningClock(600+total)}</small></header><nav class="cue-timeline-scroll" aria-label="Planned cue order"><div class="cue-timeline-track">${cues.map((c,j)=>`<button class="${cueSettings(s,j).complete?'is-complete':''}" style="flex:0 0 ${minutes[j]*8}px" data-session-cue="${j}" aria-current="${s.cue===j}" aria-label="${c[0]} ${esc(c[1])}, ${minutes[j]} minutes planned" title="${c[0]} · ${esc(c[1])} · ${minutes[j]} min">${c[0]}</button>`).join('')}</div></nav></section>`;
}
function calmPanel(s){const t=running(s),c=cues[s.cue];return `<section id="main-panel" class="calm-main-panel" aria-label="Recording controls"><div class="calm-cue"><span class="rec-status ${t?'rolling':'standby'}">${t?'● Recording · '+entryLabel(t):s.unified&&!s.sessionStarted?'● Ready to start':'● Standby'}</span><div class="main-cue"><b>${c[0]}</b><strong>${esc(c[1])}</strong></div><small>${c[2]} music · ${cuePlannedMinutes(s.cue)} min planned</small></div><div class="calm-transport">${recordButton(s)}<span ${t?`data-live="${t.id}"`:''}>${time(t?position(t):0)}</span></div><div class="calm-schedule">On schedule</div><details class="calm-session" data-calm-session ${s.calmSessionOpen?'open':''}><summary>Session details</summary>${sourceSessionSummary(s)}<div class="calm-extra-times"><span>Time <b data-wall-clock>${new Date().toLocaleTimeString('en-GB')}</b></span><span>Elapsed <b>14:42</b></span><span>Remaining <b>5:45:18</b></span></div><div class="calm-cue-actions"><button data-action="prev-cue" ${t?'disabled':''}>← Previous cue</button><button data-action="next-cue" ${t?'disabled':''}>Next cue →</button>${!t&&s.sessionStarted!==false?`<button data-action="record-overdub">Overdub ${nextEntryNumber(s,s.cue,'overdub')}</button>`:''}</div></details></section>`;}
function calmTakeRow(s,t){return `<div class="calm-take-row ${s.selected===t.id?'is-selected':''} ${t.rolling?'is-recording':''}" data-calm-take="${t.id}"><button class="calm-take-name" title="${takeShortcutTitle(t)}" data-select-take="${t.id}" aria-pressed="${s.selected===t.id}" aria-label="View notes for ${entryLabel(t)}"><b>${entryLabel(t)}</b><small>${t.rolling?'● Recording':time(t.duration)}</small></button><div class="take-tools">${starRating(t.rating,t.id,cues[t.cue][0]+' '+entryLabel(t))}<button class="best" data-take-best="${t.id}" aria-pressed="${t.best}">Best</button><button class="alt" data-take-alt="${t.id}" aria-pressed="${!!t.alt}">${altLabel(s,t.cue,t.id)}</button></div></div>`;}
function calmCueList(s){return `<div class="calm-cue-list grouped-list"><div class="cue-column-headings" aria-hidden="true"><span></span><span>Cue / Title</span><span>Length</span><span>Complexity</span><span>Planned<br>(min)</span><span>Actual</span><span>Done</span></div>${cues.map((c,j)=>{const settings=cueSettings(s,j);return `<section class="cue-group ${j===s.cue?'current':''} ${settings.complete?'is-complete':''}"><div class="calm-cue-heading"><button data-open-cue="${j}" aria-expanded="${s.open.has(j)}" aria-label="Show takes for ${c[0]}">${s.open.has(j)?'⌄':'›'}</button><button data-select-cue="${j}" aria-current="${j===s.cue}" title="${c[0]} · ${esc(c[1])}"><span class="cue-name-line"><b>${c[0]}</b><small>${entryCountText(s,j)}</small></span><span class="cue-title">${esc(c[1])}</span></button><span class="cue-music-length" aria-label="Music length for ${c[0]}">${c[2]}</span><label class="cue-complexity"><span>Complexity</span><select data-cue-complexity="${j}" aria-label="Complexity for ${c[0]}">${['Low','Medium','High'].map(value=>`<option ${settings.complexity===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="cue-planned"><span>Planned (min)</span><input type="number" min="1" max="1440" step="1" value="${settings.planned}" data-cue-planned="${j}" aria-label="Planned work in minutes for ${c[0]}"></label><div class="cue-actual-field"><span>Actual</span>${cueActual(s,j)}</div><input type="checkbox" class="cue-complete" data-cue-complete="${j}" aria-label="Mark ${c[0]} complete" ${settings.complete?'checked':''}></div><div class="calm-cue-takes" id="details-${j}" ${s.open.has(j)?'':'hidden'}>${s.takes[j].map(t=>calmTakeRow(s,t)).join('')||'<p class="notes-empty">No takes yet</p>'}</div></section>`;}).join('')}</div>`;}

function calmNotes(s){const t=takeById(s,s.selected),cue=t?.cue??s.cue;return `<section class="calm-notes" aria-label="Notes for the selected take"><header><b>${cues[cue][0]} · ${t?entryLabel(t):'Notes'}</b>${t?`<small>${t.rolling?'<span class="take-recording-status">● Recording</span>':'Selected take'}${running(s)&&running(s).id!==t.id?' <span class="take-recording-status">● '+entryLabel(running(s))+' is recording</span>':''}</small>`:''}</header>${t?`${composer(s,t,false,'calm')}${noteList(s,t,false,'calm')}`:'<p class="notes-empty">Start a take to write notes.</p>'}<details class="calm-cue-notes" data-cue-fold="${cue}" ${s.cueFold.has(cue)?'open':''}><summary>Cue notes</summary>${cueGeneral(s,cue,'calm')}</details></section>`;}
function calmControls(){const s=state();return demoTop('')+controlVersionButtons(s)+(variant==='A'?`<div class="calm-scroll control-scroll" id="cue-scroll" tabindex="0" aria-label="Recording workspace"><div class="sticky-slot" aria-hidden="true">${transport(s)}</div>${calmPanel(s)}${cueTimeline(s)}<div class="calm-content">${calmCueList(s)}${calmNotes(s)}</div></div>`:`<div class="calm-side"><aside>${calmPanel(s)}</aside><div class="calm-scroll control-scroll" id="cue-scroll" tabindex="0" aria-label="Cues and notes">${cueTimeline(s)}<div class="calm-content">${calmCueList(s)}${calmNotes(s)}</div></div></div>`);}
async function fullscreenPrototype(){const frame=document.querySelector('.browser-frame');if(!frame)return;try{if(document.fullscreenElement)await document.exitFullscreen();else if(frame.requestFullscreen)await frame.requestFullscreen();else frame.classList.toggle('prototype-expanded');}catch{frame.classList.toggle('prototype-expanded');}syncFullscreenButtons();scheduleRecordingControls();}
function syncFullscreenButtons(){const expanded=!!document.fullscreenElement||!!document.querySelector('.prototype-expanded');document.querySelectorAll('[data-action="fullscreen-prototype"]').forEach(b=>b.textContent=expanded?'↙ Exit full screen':'⛶ Full screen');}
document.addEventListener('fullscreenchange',()=>{syncFullscreenButtons();scheduleRecordingControls();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.prototype-expanded')?.classList.remove('prototype-expanded');syncFullscreenButtons();}});
